/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { StringManager } from "../../src/i18n/StringManager.js";
import { InfraredScreen } from "../../src/infrared/InfraredScreen.js";
import { NMRScreen } from "../../src/nmr/NMRScreen.js";
import { SpectroscopyLabPreferencesModel } from "../../src/preferences/SpectroscopyLabPreferencesModel.js";
import SpectroscopyLabColors from "../../src/SpectroscopyLabColors.js";
import { UnknownsScreen } from "../../src/unknowns/UnknownsScreen.js";
import { UVVisScreen } from "../../src/uv-vis/UVVisScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from spectroscopyLabQueryParameters.
  const simPreferences = new SpectroscopyLabPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new InfraredScreen(simPreferences, {
      name: stringManager.getScreenNames().infraredStringProperty,
      tandem: Tandem.ROOT.createTandem("infraredScreen"),
      backgroundColorProperty: SpectroscopyLabColors.backgroundColorProperty,
    }),
    new NMRScreen({
      name: stringManager.getScreenNames().nmrStringProperty,
      tandem: Tandem.ROOT.createTandem("nmrScreen"),
      backgroundColorProperty: SpectroscopyLabColors.backgroundColorProperty,
    }),
    new UVVisScreen({
      name: stringManager.getScreenNames().uvVisStringProperty,
      tandem: Tandem.ROOT.createTandem("uvVisScreen"),
      backgroundColorProperty: SpectroscopyLabColors.backgroundColorProperty,
    }),
    new UnknownsScreen({
      name: stringManager.getScreenNames().unknownsStringProperty,
      tandem: Tandem.ROOT.createTandem("unknownsScreen"),
      backgroundColorProperty: SpectroscopyLabColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { SpectroscopyLabColors, stringManager, simPreferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
